// Extract tools from MCP response
const mcpResult = input.result;
let tools = [];

if (mcpResult && mcpResult.result && mcpResult.result.tools) {
  tools = mcpResult.result.tools;
} else if (mcpResult && mcpResult.tools) {
  tools = mcpResult.tools;
}

console.log("Available tools:", JSON.stringify(tools, null, 2));

// Get execution strategy from input
const strategy = input.strategy || 'single'; // 'single', 'multiple', 'all', 'filter'
const targetTools = input.targetTools || input.toolNames || [];
const toolFilter = input.toolFilter || input.filter; // regex or substring
const maxExecutions = input.maxExecutions || 5;

let toolsToExecute = [];

switch (strategy) {
  case 'single':
    const singleTool = input.targetTool || input.toolName;
    if (singleTool) {
      const tool = tools.find(t => t.name === singleTool);
      if (tool) toolsToExecute = [tool];
    }
    break;

  case 'multiple':
    toolsToExecute = tools.filter(t => targetTools.includes(t.name));
    break;

  case 'all':
    toolsToExecute = tools.slice(0, maxExecutions);
    break;

  case 'filter':
    if (toolFilter) {
      const regex = new RegExp(toolFilter, 'i');
      toolsToExecute = tools.filter(t => 
        regex.test(t.name) || 
        (t.description && regex.test(t.description))
      ).slice(0, maxExecutions);
    }
    break;
}

if (toolsToExecute.length === 0) {
  return {
    error: "No tools selected for execution",
    availableTools: tools,
    strategy: strategy,
    criteria: { targetTools, toolFilter, maxExecutions }
  };
}

return {
  availableTools: tools,
  toolsToExecute: toolsToExecute,
  executionPlan: {
    strategy: strategy,
    totalTools: tools.length,
    selectedCount: toolsToExecute.length,
    toolNames: toolsToExecute.map(t => t.name)
  },
  currentIndex: 0,
  executionResults: [],
  ready: true
};

const currentIndex = input.currentIndex || 0;
const toolsToExecute = input.toolsToExecute || [];

if (currentIndex >= toolsToExecute.length) {
  return {
    ...input,
    allComplete: true,
    message: "All tools executed successfully"
  };
}

const currentTool = toolsToExecute[currentIndex];
const toolParams = input.toolParameters || input.toolParams || {};

// Allow per-tool parameters
const perToolParams = input.perToolParams || {};
const currentParams = perToolParams[currentTool.name] || toolParams;

return {
  ...input,
  currentTool: currentTool,
  toolName: currentTool.name,
  toolParameters: JSON.stringify(currentParams),
  executionReady: true
};

const currentIndex = input.currentIndex || 0;
const executionResults = input.executionResults || [];

// Record this execution
const result = {
  toolName: input.toolName,
  success: true,
  result: input.result,
  executedAt: new Date().toISOString(),
  index: currentIndex
};

executionResults.push(result);

// Prepare for next iteration
const nextIndex = currentIndex + 1;
const toolsToExecute = input.toolsToExecute || [];

return {
  ...input,
  executionResults: executionResults,
  currentIndex: nextIndex,
  lastResult: result
};

const currentIndex = input.currentIndex || 0;
const executionResults = input.executionResults || [];

// Record this execution failure
const result = {
  toolName: input.toolName,
  success: false,
  error: input.error || "Execution failed",
  executedAt: new Date().toISOString(),
  index: currentIndex
};

executionResults.push(result);

// Prepare for next iteration (continue despite error)
const nextIndex = currentIndex + 1;

return {
  ...input,
  executionResults: executionResults,
  currentIndex: nextIndex,
  lastResult: result
};

const executionResults = input.executionResults || [];
const successful = executionResults.filter(r => r.success);
const failed = executionResults.filter(r => !r.success);

return {
  success: true,
  summary: {
    totalExecutions: executionResults.length,
    successful: successful.length,
    failed: failed.length,
    executionPlan: input.executionPlan
  },
  results: executionResults,
  availableTools: input.availableTools,
  completedAt: new Date().toISOString()
};

return {
  success: false,
  error: input.error || "No tools selected for execution",
  availableTools: input.availableTools || [],
  criteria: input.criteria || {},
  timestamp: new Date().toISOString()
};

return {
  success: false,
  error: "MCP operation failed: " + (input.error || "Unknown error"),
  timestamp: new Date().toISOString()
};
